from pathlib import Path
import base64

# Approved iCE Inventory LLC launcher artwork (optimized for Android launcher size).
LOGO_B64=''''''

out=Path('app/src/main/res/drawable-nodpi/ice_inventory_logo.jpg')
out.parent.mkdir(parents=True,exist_ok=True)
out.write_bytes(base64.b64decode(LOGO_B64))

manifest=Path('app/src/main/AndroidManifest.xml')
s=manifest.read_text().replace('android:icon="@drawable/ice_onhand_icon"','android:icon="@drawable/ice_inventory_logo"')
manifest.write_text(s)

b=Path('app/build.gradle')
g=b.read_text().replace('versionCode 30033','versionCode 30034').replace("versionName '3.0.33'","versionName '3.0.34'")
b.write_text(g)
